// === Tab: mySketch ===
//Credit to the original sketch creator Antrague (https://openprocessing.org/user/68165/) and previous individuals that forked this 
//(Richard Bourne https://openprocessing.org/user/162823/) and clustah (https://openprocessing.org/user/92042/?view=sketches)

let particles1 = []; //1. pole castic
let num = 10000; //pocet castic
let counter=0

function setup() 
{
	createCanvas(16/9*windowHeight, windowHeight);
	background(0);
	for(let i=0;i<num;i++)
	{
    particles1.push(createVector(random(width), random(height))) 
			//randomne rozmistime castice po obrazovce
	}
}

function draw() 
{
	if(counter<28) 
	{
		counter++
		colorMode(HSB);
		// blendMode(ADD);
		if(counter<10) stroke("green")
		else stroke (60+counter,30,counter+40, 50);
		for(let i=0;i<num;i++)
		{
			let p = particles1[i];
			if(counter>10) point(p.x+random(-3,10), p.y);
			else if(counter<10) point(p.x+random(-3,10), p.y+random(50));
			p.x+=(noise(p.x/200,p.y/200,300000000)-0.54)*2;
			p.y+=(noise(p.x/200,p.y/200,30000)-0.5)*20;
  	}
	}
}

function keyPressed(){
  save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
}

